<?php $s=$pdo->prepare('SELECT full_name,email,role FROM users WHERE id=?');$s->execute([user()['id']]);$r=$s->fetch();layout_start('Your account'); ?><div class="page-heading"><div><p class="eyebrow">ACCOUNT</p><h1>Your account</h1><p class="muted">Your CareShare sign-in profile.</p></div></div><section class="panel profile-card"><div class="avatar"><?=h(strtoupper(substr($r['full_name'],0,1)))?></div><dl class="detail-list"><dt>Name</dt><dd><?=h($r['full_name'])?></dd><dt>Email</dt><dd><?=h($r['email'])?></dd><dt>Role</dt><dd><?=h($r['role'])?></dd></dl><p class="muted">For password or account changes, contact a CareShare administrator.</p></section><?php layout_end();
